const npmrcTracked = makeGitRepo("npmrc-tracked", { ".npmrc": "auto-install-peers=true\n", "apps/web/.npmrc": "strict-peer-dependencies=false\n" }, [".npmrc", "apps/web/.npmrc"]);
const npmrcUntracked = makeGitRepo("npmrc-untracked", { ".npmrc": "//registry.npmjs.org/:_authToken=secret\n" });

// The pass-9 reviewer's project: an untracked root .env and .env.local, a committed apps/web/.env and
// .npmrc, and an uncommitted packages/api/.env.local.
const pass9Project = makeGitRepo(
  "everyday-pass9",
  {
    ".env.example": "API=\n",
    ".env.local": "SECRET=1\n",
    ".env": "SECRET=2\n",
    "apps/web/.env": "X=\n",
    "apps/web/.env.example": "X=\n",
    "packages/api/.env.local": "S=3\n",
    "packages/api/.env.example": "S=\n",
    ".npmrc": "auto-install-peers=true\n",
    "package.json": "{}",
    "src/app.ts": "x",
    "logs/app.log": "log\n",
    "msg.txt": "feat(web): add form\n\nBody.\n",
    "bad.txt": "Fixed stuff.\n"
  },
  [".env.example", "apps/web/.env", "apps/web/.env.example", ".npmrc", "package.json", "src/app.ts"]
);
const pass9Forward = pass9Project.split(B).join("/");
const inPass9Project = (commandOrInput) => JSON.parse(JSON.stringify(commandOrInput).split("__P__").join(pass9Forward));

